BEGIN;

-- ── 客户（母方案 :440-445）────────────────────────────────────────────
-- 设计意图：必须有重复国家（Brazil×2）用来测「国家筛选」是否落进 SQL；
--          必须有一条 country=NULL 用来测「未知国家 ≠ 非巴西」这个最易错的口径。
INSERT INTO customer (customer_id, country, city) VALUES
    (1, 'Brazil', 'Sao Paulo'),
    (2, 'Brazil', 'Rio'),
    (3, 'USA',    'Boston'),
    (4, NULL,     NULL);

-- ── 发票（母方案 :449-458）────────────────────────────────────────────
-- 设计意图（每一条都不是随便填的）：
--   :451 11 - 2023-01-01T00:00:00Z 100.00  边界：金额恰好 100，年初第一秒
--   :452 12 - 2023-06-15T10:00:00Z 200.00  年中
--   :453 13 - 2022-12-31T23:59:59Z  50.00  边界：跨年前最后一秒（若被算进 2023 = 错）
--   :454 14 - 2024-01-01T00:00:00Z 300.00  边界：2024 第一秒
--   :455 15 - 2023-12-31T23:59:59Z 100.01  边界：2023 最后一秒 +「略大于 100」
--   :456 16 - 2024-05-01T10:00:00Z  99.99  边界：「略小于 100」
--   :457 17 - 2024-06-15T10:00:00Z 100.00  边界：时间锚点当日（应计入「截至 6/15」）
--   :458 18 - 2024-06-16T00:00:00Z 400.00  边界：锚点次日第一秒（**不得**计入「截至 6/15」）
--
-- 客户分布：1→3 张(11,12,17) / 2→2 张(13,15) / 3→2 张(14,16) / 4→**0 张**（无发票客户）
INSERT INTO invoice (invoice_id, customer_id, invoice_date, total) VALUES
    (11, 1, '2023-01-01T00:00:00Z', 100.00),
    (12, 1, '2023-06-15T10:00:00Z', 200.00),
    (13, 2, '2022-12-31T23:59:59Z',  50.00),
    (14, 3, '2024-01-01T00:00:00Z', 300.00),
    (15, 2, '2023-12-31T23:59:59Z', 100.01),
    (16, 3, '2024-05-01T10:00:00Z',  99.99),
    (17, 1, '2024-06-15T10:00:00Z', 100.00),
    (18, 1, '2024-06-16T00:00:00Z', 400.00);

-- ── 员工（母方案 :464）───────────────────────────────────────────────
-- 只有编号与入职日期。本表**刻意**没有离职/有效期/快照字段：
-- 2023 年新入职人数可由本表证明（=1），但「2023 年在职人数」不能。
-- 测试必须确认系统如实说明该缺口，而不是编造离职日期。
INSERT INTO employee (employee_id, hire_date) VALUES
    (1, '2022-01-01'),
    (2, '2023-06-01'),
    (3, '2024-06-01');

-- ── SC-20 分组样本（母方案 :466）──────────────────────────────────────
-- 「客户数大于 5 的国家」只有 Brazil(6)。保留该人群后按城市细分 = Sao Paulo 4 / Rio 2。
-- 两类错误必须都被发现：
--   ① 删掉原国家筛选 → 会多出 USA/Canada
--   ② 把旧 HAVING 机械搬到城市粒度 → 得到空集
INSERT INTO country_group (country, city, customer_count) VALUES
    ('Brazil', 'Sao Paulo', 4),
    ('Brazil', 'Rio',       2),
    ('USA',    'Boston',    5),
    ('Canada', 'Toronto',   1);

